INSERT INTO agent_actions VALUES(5496,'2026-03-16 04:43:01','3aa5db94-0ee8-45e0-921d-42b00d105f4a','context-mode','jarvis','Read','(\"Edit\", \"Write\", \"MultiEdit\"):\n    path = inp.get(\"file_path\", inp.get(\"path\", \"\"))\n    if path and path.endswith(\".py\"):\n        try:\n            subprocess.run([\"black\", \"--quiet\", path], capture_output=True, timeout=10)\n        except Exception:\n            pass\n\n# ── Patch 5: métricas en try/except — nunca bloquean trabajo real ──\ntry:\n    import sqlite3\n\n    DB = os.path.join(\n        os.environ.get(\"JARVIS_ROOT\", \"/root/jarvis\"), \"database\", \"jarvis_metrics.db\"\n    )\n    if os.path.exists(DB):\n        success = 1 if resp.get(\"exit_code\", 0) == 0 else 0\n        error_msg = (resp.get(\"stderr\") or resp.get(\"error\") or \"\")[:500]\n        content = inp.get(\"new_content\", inp.get(\"content\", \"\"))\n        bytes_wr = len(content.encode(\"utf-8\", errors=\"replace\")) if content else 0\n        # Cuando falla sin stderr: registrar tool + motivo genérico para auditoría\n        stored_error = error_msg or (f\"{tool} falló (sin stderr)\" if not success else None)\n\n        conn = sqlite3.connect(DB, timeout=2)\n        # Cerrar la acción abierta por pre_tool_use (más reciente sin end_time)\n        conn.execute(\n            \"\"\"\n            UPDATE agent_actions\n            SET end_time_ms=?, duration_ms=?-COALESCE(start_time_ms,?),\n                success=?, error_message=?, bytes_written=?\n            WHERE id=(\n                SELECT id FROM agent_actions\n                WHERE session_id=? AND tool_used=? AND end_time_ms IS NULL\n                ORDER BY id DESC LIMIT 1)\n        \"\"\",\n            (now_ms, now_ms, now_ms, success, stored_error, bytes_wr, session, tool),\n        )\n\n        if not success:\n            conn.execute(\n                \"INSERT INTO error_log \"\n                \"(session_id,agent_name,error_type,error_message,keywords) \"\n                \"VALUES (?,?,?,?,?)\",\n                (session, agent, f\"{tool}Error\", stored_error or f\"{tool} failed\", \"[]\"),\n            )\n        conn.commit()\n        conn.close()\nexcept Exception:\n    pass  # logging falla silenciosamente\n\nsys.exit(0)\n","numLines":74,"startLine":1,"totalLines":74}}','read',NULL,NULL,NULL,NULL,NULL,1,NULL,0,'["(\\\"Edit\\\", \\\"Write\\\", \\\"MultiEdit\\\"):\\n    path = inp.get(\\\"file_path\\\", inp.get(\\\"path\\\", \\\"\\\"))\\n    if path and path.endswith(\\\".py\\\"):\\n        try:\\n            subprocess.run([\\\"black\\\", \\\"--quiet\\\", path], capture_output=True, timeout=10)\\n        except Exception:\\n            pass\\n\\n# \u2500\u2500 Patch 5: m\u00e9tricas en try/except \u2014 nunca bloquean trabajo real \u2500\u2500\\ntry:\\n    import sqlite3\\n\\n    DB = os.path.join(\\n        os.environ.get(\\\"JARVIS_ROOT\\\", \\\"/root/jarvis\\\"), \\\"database\\\", \\\"jarvis_metrics.db\\\"\\n    )\\n    if os.path.exists(DB):\\n        success = 1 if resp.get(\\\"exit_code\\\", 0) == 0 else 0\\n        error_msg = (resp.get(\\\"stderr\\\") or resp.get(\\\"error\\\") or \\\"\\\")[:500]\\n        content = inp.get(\\\"new_content\\\", inp.get(\\\"content\\\", \\\"\\\"))\\n        bytes_wr = len(content.encode(\\\"utf-8\\\", errors=\\\"replace\\\")) if content else 0\\n        # Cuando falla sin stderr: registrar tool + motivo gen\u00e9rico para auditor\u00eda\\n        stored_error = error_msg or (f\\\"{tool} fall\u00f3 (sin stderr)\\\" if not success else None)\\n\\n        conn = sqlite3.connect(DB, timeout=2)\\n        # Cerrar la acci\u00f3n abierta por pre_tool_use (m\u00e1s reciente sin end_time)\\n        conn.execute(\\n            \\\"\\\"\\\"\\n            UPDATE agent_actions\\n            SET end_time_ms=?, duration_ms=?-COALESCE(start_time_ms,?),\\n                success=?, error_message=?, bytes_written=?\\n            WHERE id=(\\n                SELECT id FROM agent_actions\\n                WHERE session_id=? AND tool_used=? AND end_time_ms IS NULL\\n                ORDER BY id DESC LIMIT 1)\\n        \\\"\\\"\\\",\\n            (now_ms, now_ms, now_ms, success, stored_error, bytes_wr, session, tool),\\n        )\\n\\n        if not success:\\n            conn.execute(\\n                \\\"INSERT INTO error_log \\\"\\n                \\\"(session_id,agent_name,error_type,error_message,keywords) \\\"\\n                \\\"VALUES (?,?,?,?,?)\\\",\\n                (session, agent, f\\\"{tool}Error\\\", stored_error or f\\\"{tool} failed\\\", \\\"[]\\\"),\\n            )\\n        conn.commit()\\n        conn.close()\\nexcept Exception:\\n    pass  # logging falla silenciosamente\\n\\nsys.exit(0)\\n\",\"numLines\":74,\"startLine\":1,\"totalLines\":74}}"]',NULL,'[]',0,0.0,0,0,0,0.0,'unknown',0,NULL,0,0.0,0.0);
