INSERT INTO agent_actions VALUES(7824,'2026-03-18 13:11:08','410467b9-bd2a-4026-99ea-48965fbab910','context-mode','jarvis','Read','{"type":"text","file":{"filePath":"/root/jarvis/.claude/hooks/postcompact.py","content":"#!/usr/bin/env python3\n\"\"\"\nJARVIS Hook — PostCompact\nRegistra el evento de compactación en DB.\n\nPostCompact NO soporta additionalContext — la reinyección de contexto\nla maneja session_start.py (SessionStart se dispara con source=\"compact\").\nEste hook solo persiste el conteo de compactaciones en la DB.\nExit 0 siempre.\n\"\"\"\n\nimport json\nimport os\nimport sqlite3\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nJARVIS = Path(os.environ.get(\"JARVIS_ROOT\", \"/root/jarvis\"))\nDB = JARVIS / \"database\" / \"jarvis_metrics.db\"\nSTATE_FILE = JARVIS / \"tasks\" / \"precompact_state.json\"\n\ntry:\n    data = json.load(sys.stdin)\nexcept Exception:\n    data = {}\n\n# ── Recuperar estado pre-compact ────────────────────────────────────\npre_state: dict = {}\ntry:\n    if STATE_FILE.exists():\n        pre_state = json.loads(STATE_FILE.read_text(encoding=\"utf-8\"))\nexcept Exception:\n    pass\n\nproject = pre_state.get(\"project\") or os.environ.get(\"JARVIS_PROJECT\", \"\") or \"jarvis-core\"\nsession_id = pre_state.get(\"session_id\", os.environ.get(\"CLAUDE_SESSION_ID\", \"unknown\"))\n\n# ── Registrar compactación en DB ─────────────────────────────────────\ntry:\n    if DB.exists():\n        conn = sqlite3.connect(str(DB), timeout=2)\n        conn.execute(\n            \"UPDATE sessions SET compact_count = COALESCE(compact_count, 0) + 1 \"\n            \"WHERE session_id=?\",\n            (session_id,),\n        )\n        conn.commit()\n        conn.close()\nexcept Exception:\n    pass\n\nprint(json.dumps({\"suppressOutput\": True}))\nsys.exit(0)\n","numLines":55,"startLine":1,"totalLines":55}}','read',NULL,NULL,NULL,NULL,NULL,1,NULL,0,'["{\"type\":\"text\",\"file\":{\"filePath\":\"/root/jarvis/.claude/hooks/postcompact.py\",\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"\\nJARVIS Hook \u2014 PostCompact\\nRegistra el evento de compactaci\u00f3n en DB.\\n\\nPostCompact NO soporta additionalContext \u2014 la reinyecci\u00f3n de contexto\\nla maneja session_start.py (SessionStart se dispara con source=\\\"compact\\\").\\nEste hook solo persiste el conteo de compactaciones en la DB.\\nExit 0 siempre.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport sqlite3\\nimport sys\\nfrom datetime import datetime\\nfrom pathlib import Path\\n\\nJARVIS = Path(os.environ.get(\\\"JARVIS_ROOT\\\", \\\"/root/jarvis\\\"))\\nDB = JARVIS / \\\"database\\\" / \\\"jarvis_metrics.db\\\"\\nSTATE_FILE = JARVIS / \\\"tasks\\\" / \\\"precompact_state.json\\\"\\n\\ntry:\\n    data = json.load(sys.stdin)\\nexcept Exception:\\n    data = {}\\n\\n# \u2500\u2500 Recuperar estado pre-compact \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\npre_state: dict = {}\\ntry:\\n    if STATE_FILE.exists():\\n        pre_state = json.loads(STATE_FILE.read_text(encoding=\\\"utf-8\\\"))\\nexcept Exception:\\n    pass\\n\\nproject = pre_state.get(\\\"project\\\") or os.environ.get(\\\"JARVIS_PROJECT\\\", \\\"\\\") or \\\"jarvis-core\\\"\\nsession_id = pre_state.get(\\\"session_id\\\", os.environ.get(\\\"CLAUDE_SESSION_ID\\\", \\\"unknown\\\"))\\n\\n# \u2500\u2500 Registrar compactaci\u00f3n en DB \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\ntry:\\n    if DB.exists():\\n        conn = sqlite3.connect(str(DB), timeout=2)\\n        conn.execute(\\n            \\\"UPDATE sessions SET compact_count = COALESCE(compact_count, 0) + 1 \\\"\\n            \\\"WHERE session_id=?\\\",\\n            (session_id,),\\n        )\\n        conn.commit()\\n        conn.close()\\nexcept Exception:\\n    pass\\n\\nprint(json.dumps({\\\"suppressOutput\\\": True}))\\nsys.exit(0)\\n\",\"numLines\":55,\"startLine\":1,\"totalLines\":55}}"]',NULL,'[]',0,0.0,0,0,0,0.0,'unknown',0,NULL,0,0.0,0.0);
