INSERT INTO agent_actions VALUES(8983,'2026-03-19 02:11:03','9e00834a-f507-4850-b8c4-a2a660b5b730','context-mode','jarvis','Read','{"type":"text","file":{"filePath":"/root/jarvis/.claude/hooks/postcompact.py","content":"#!/usr/bin/env python3\n\"\"\"\nJARVIS Hook — PostCompact\nRegistra el evento de compactación en DB.\n\nPostCompact NO soporta additionalContext — la reinyección de contexto\nla maneja session_start.py (SessionStart se dispara con source=\"compact\").\nEste hook solo persiste el conteo de compactaciones en la DB.\nExit 0 siempre.\n\"\"\"\n\nimport json\nimport os\nimport sqlite3\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nJARVIS = Path(os.environ.get(\"JARVIS_ROOT\", \"/root/jarvis\"))\nDB = JARVIS / \"database\" / \"jarvis_metrics.db\"\nSTATE_FILE = JARVIS / \"tasks\" / \"precompact_state.json\"\n\ntry:\n    data = json.load(sys.stdin)\nexcept Exception:\n    data = {}\n\n# ── Recuperar estado pre-compact ────────────────────────────────────\npre_state: dict = {}\ntry:","numLines":30,"startLine":1,"totalLines":55}}','read',NULL,NULL,NULL,NULL,NULL,1,NULL,0,'["{\"type\":\"text\",\"file\":{\"filePath\":\"/root/jarvis/.claude/hooks/postcompact.py\",\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"\\nJARVIS Hook \u2014 PostCompact\\nRegistra el evento de compactaci\u00f3n en DB.\\n\\nPostCompact NO soporta additionalContext \u2014 la reinyecci\u00f3n de contexto\\nla maneja session_start.py (SessionStart se dispara con source=\\\"compact\\\").\\nEste hook solo persiste el conteo de compactaciones en la DB.\\nExit 0 siempre.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport sqlite3\\nimport sys\\nfrom datetime import datetime\\nfrom pathlib import Path\\n\\nJARVIS = Path(os.environ.get(\\\"JARVIS_ROOT\\\", \\\"/root/jarvis\\\"))\\nDB = JARVIS / \\\"database\\\" / \\\"jarvis_metrics.db\\\"\\nSTATE_FILE = JARVIS / \\\"tasks\\\" / \\\"precompact_state.json\\\"\\n\\ntry:\\n    data = json.load(sys.stdin)\\nexcept Exception:\\n    data = {}\\n\\n# \u2500\u2500 Recuperar estado pre-compact \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\\npre_state: dict = {}\\ntry:\",\"numLines\":30,\"startLine\":1,\"totalLines\":55}}"]',NULL,'[]',0,0.0,0,0,0,0.0,'unknown',0,NULL,0,0.0,0.0);
