INSERT INTO vector_chunks_backup_20260327 VALUES(63,'ai_ml/papers/paper_trust_by_design_skill_profiles_for_transparent_cost_aware_ll.md',2,'','applied_sciences',replace('## Core Insight\nHow should Large Language Model (LLM) practitioners select the right model for a task without wasting money? We introduce BELLA (Budget-Efficient LLM Selection via Automated skill-profiling), a framework that recommends optimal LLM selection for tasks through interpretable skill-based model selection. Standard benchmarks report aggregate metrics that obscure which specific capabilities a task requires and whether a cheaper model could suffice. BELLA addresses this gap through three stages: (1) d','\n',char(10)),'2026-03-25 17:18:35');
