INSERT INTO vector_chunks_backup_20260327 VALUES(218,'algorithms/papers/paper_bridging_semantic_and_kinematic_conditions_with_diffusion_ba.md',2,'','formal_sciences',replace('## Core Insight\nPrior motion generation largely follows two paradigms: continuous diffusion models that excel at kinematic control, and discrete token-based generators that are effective for semantic conditioning. To combine their strengths, we propose a three-stage framework comprising condition feature extraction (Perception), discrete token generation (Planning), and diffusion-based motion synthesis (Control). Central to this framework is MoTok, a diffusion-based discrete motion tokenizer that decouples sema','\n',char(10)),'2026-03-25 17:19:22');
