INSERT INTO vector_chunks_backup_20260327 VALUES(254,'algorithms/papers/paper_mme_cof_pro_evaluating_reasoning_coherence_in_video_generati.md',2,'','formal_sciences',replace('## Core Insight\nVideo generative models show emerging reasoning behaviors. It is essential to ensure that generated events remain causally consistent across frames for reliable deployment, a property we define as reasoning coherence. To bridge the gap in literature for missing reasoning coherence evaluation, we propose MME-CoF-Pro, a comprehensive video reasoning benchmark to assess reasoning coherence in video models. Specifically, MME-CoF-Pro contains 303 samples across 16 categories, ranging from visual logi','\n',char(10)),'2026-03-25 17:19:22');
