INSERT INTO vector_chunks_backup_20260327 VALUES(266,'algorithms/papers/paper_videodetective_clue_hunting_via_both_extrinsic_query_and_int.md',2,'','formal_sciences',replace('## Core Insight\nLong video understanding remains challenging for multimodal large language models (MLLMs) due to limited context windows, which necessitate identifying sparse query-relevant video segments. However, existing methods predominantly localize clues based solely on the query, overlooking the video''s intrinsic structure and varying relevance across segments. To address this, we propose VideoDetective, a framework that integrates query-to-segment relevance and inter-segment affinity for effective clue','\n',char(10)),'2026-03-25 17:19:22');
