INSERT INTO vector_chunks_backup_20260327 VALUES(301,'mathematics/papers/paper_f2llm_v2_inclusive_performant_and_efficient_embeddings_for_a.md',2,'','formal_sciences',replace('## Core Insight\nWe present F2LLM-v2, a new family of general-purpose, multilingual embedding models in 8 distinct sizes ranging from 80M to 14B. Trained on a newly curated composite of 60 million publicly available high-quality data samples, F2LLM-v2 supports more than 200 languages, with a particular emphasis on previously underserved mid- and low-resource languages. By integrating a two-stage LLM-based embedding training pipeline with matryoshka learning, model pruning, and knowledge distillation techniques,','\n',char(10)),'2026-03-25 17:19:22');
