INSERT INTO vector_chunks_backup_20260327 VALUES(450,'film_music_data_reference.md',5,'','humanities_arts',replace('## RIAA Certification Thresholds (USA)\n\n| Award | Singles (streams equivalent) | Albums (units) |\n|-------|------------------------------|----------------|\n| Gold | 500,000 | 500,000 |\n| Platinum | 1,000,000 | 1,000,000 |\n| Multi-Platinum | 2,000,000+ | 2,000,000+ |\n| Diamond | 10,000,000 | 10,000,000 |\n\nStreaming equivalent: 150 streams = 1 track sale (as of 2016). 10 track sales = 1 album unit.\nMost RIAA-certified albums: The Beatles (~183M), Garth Brooks (~157M), Elvis Presley (~146M), Led Zeppelin (~111M).','\n',char(10)),'2026-03-25 17:19:23');
