INSERT INTO vector_chunks_backup_20260327 VALUES(548,'biology/papers/paper_conditioning_protein_generation_via_hopfield_pattern_multipl.md',0,'','natural_sciences','# Conditioning Protein Generation via Hopfield Pattern Multiplicity','2026-03-25 17:19:24');
INSERT INTO vector_chunks_backup_20260327 VALUES(549,'biology/papers/paper_conditioning_protein_generation_via_hopfield_pattern_multipl.md',1,'','natural_sciences',replace('## Source\n- Published: 2026-03-20\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.20115v1\n- Retrieved: 2026-03-23','\n',char(10)),'2026-03-25 17:19:24');
INSERT INTO vector_chunks_backup_20260327 VALUES(550,'biology/papers/paper_conditioning_protein_generation_via_hopfield_pattern_multipl.md',2,'','natural_sciences',replace('## Core Insight\nProtein sequence generation via stochastic attention produces plausible family members from small alignments without training, but treats all stored sequences equally and cannot direct generation toward a functional subset of interest. We show that a single scalar parameter, added as a bias to the sampler''s attention logits, continuously shifts generation from the full family toward a user-specified subset, with no retraining and no change to the model architecture. A practitioner supplies a sma','\n',char(10)),'2026-03-25 17:19:24');
INSERT INTO vector_chunks_backup_20260327 VALUES(551,'biology/papers/paper_conditioning_protein_generation_via_hopfield_pattern_multipl.md',3,'','natural_sciences','## Key Concepts','2026-03-25 17:19:24');
