INSERT INTO vector_chunks_backup_20260327 VALUES(616,'chemistry/papers/paper_classification_of_uncolored_bonded_knots_and_links.md',2,'','natural_sciences',replace('## Core Insight\nWe present a systematic classification of uncolored bonded knots with singularity number at most seven. Bonded knots provide a topological model for closed protein chains with intramolecular bridges, such as disulfide bonds. Following the tradition of knot tabulation, we describe a procedure based on the generation of planar graphs, their conversion into bonded knot diagrams, and the use of the Yamada polynomial together with brute-force Reidemeister moves to distinguish topological knotted type','\n',char(10)),'2026-03-25 17:19:25');
