INSERT INTO vector_chunks_backup_20260327 VALUES(723,'physics/papers/paper_duo_vsr_dual_stream_distillation_for_one_step_video_super_re.md',2,'','natural_sciences',replace('## Core Insight\nDiffusion-based video super-resolution (VSR) has recently achieved remarkable fidelity but still suffers from prohibitive sampling costs. While distribution matching distillation (DMD) can accelerate diffusion models toward one-step generation, directly applying it to VSR often results in training instability alongside degraded and insufficient supervision. To address these issues, we propose DUO-VSR, a three-stage framework built upon a Dual-Stream Distillation strategy that unifies distributio','\n',char(10)),'2026-03-25 17:19:25');
