INSERT INTO vector_chunks_backup_20260327 VALUES(801,'business/papers/paper_leveraging_generative_artificial_intelligence_for_sustainabl.md',2,'','social_sciences',replace('## Core Insight\nThis study develops an integrated framework, termed the GAI&ABC model, to examine how manufacturing firms can leverage generative artificial intelligence (GAI) to achieve sustainable business model innovation (SBMI) in production systems. While prior research primarily focuses on the technical aspects of AI, we address the challenge of understanding the organisational learning mechanisms that underpin GAI''s impact on SBMI. Drawing on the Antecedents-Behaviour-Consequences (ABC) model, we investi','\n',char(10)),'2026-03-25 17:19:26');
