INSERT INTO vector_chunks_backup_20260327 VALUES(836,'business/papers/paper_videodetective_clue_hunting_via_both_extrinsic_query_and_int.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-23\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.22285v1\n- Retrieved: 2026-03-24','\n',char(10)),'2026-03-25 17:19:26');
INSERT INTO vector_chunks_backup_20260327 VALUES(837,'business/papers/paper_videodetective_clue_hunting_via_both_extrinsic_query_and_int.md',2,'','social_sciences',replace('## Core Insight\nLong video understanding remains challenging for multimodal large language models (MLLMs) due to limited context windows, which necessitate identifying sparse query-relevant video segments. However, existing methods predominantly localize clues based solely on the query, overlooking the video''s intrinsic structure and varying relevance across segments. To address this, we propose VideoDetective, a framework that integrates query-to-segment relevance and inter-segment affinity for effective clue','\n',char(10)),'2026-03-25 17:19:26');
