INSERT INTO vector_chunks_backup_20260327 VALUES(934,'finance/accounting/financial_statements.md',1,'','social_sciences',replace('## Three Core Statements\n1. **Income Statement**: Revenue → COGS → Gross Profit → OpEx → EBIT → Interest → EBT → Tax → Net Income\n2. **Balance Sheet**: Assets = Liabilities + Equity (snapshot)\n3. **Cash Flow Statement**: Operating + Investing + Financing = ΔCash','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(935,'finance/accounting/financial_statements.md',2,'','social_sciences',replace('## Key Linkages\n- Net Income flows from Income Statement to Retained Earnings (BS)\n- Depreciation: non-cash expense on IS, added back in CFO\n- CapEx: reduces cash (CFI), increases PP&E (BS)\n- Debt issuance: increases cash (CFF), increases liabilities (BS)','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(936,'finance/accounting/financial_statements.md',3,'','social_sciences',replace('## Operating Cash Flow (Indirect Method)\n```\nCFO = Net Income + Depreciation + ΔWorking Capital\nΔWC = ΔAR + ΔInventory - ΔAP\n```\nPositive CFO > Net Income = high earnings quality.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(937,'finance/accounting/financial_statements.md',4,'','social_sciences',replace('## Free Cash Flow\n```\nFCFF = EBIT×(1-t) + D&A - CapEx - ΔWC\nFCFE = FCFF - Interest×(1-t) + Net Borrowing\n```\n- FCFF: available to all capital providers\n- FCFE: available to equity holders only','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(938,'finance/accounting/financial_statements.md',5,'','social_sciences',replace('## Red Flags\n- Revenue growing faster than CFO (aggressive accruals)\n- Increasing receivables as % of revenue (channel stuffing)\n- Capitalizing expenses (inflating assets, understating expenses)\n- Off-balance-sheet liabilities (operating leases pre-IFRS 16)','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(939,'finance/accounting/ratio_analysis.md',0,'','social_sciences','# Financial Ratio Analysis','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(940,'finance/accounting/ratio_analysis.md',1,'','social_sciences',replace('## Profitability\n```\nGross Margin = Gross Profit / Revenue\nOperating Margin = EBIT / Revenue\nNet Margin = Net Income / Revenue\nROE = Net Income / Equity\nROA = Net Income / Total Assets\nROIC = NOPAT / Invested Capital\n```\nDuPont: ROE = Margin × Turnover × Leverage','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(941,'finance/accounting/ratio_analysis.md',2,'','social_sciences',replace('## Liquidity\n```\nCurrent Ratio = Current Assets / Current Liabilities (>1.5 healthy)\nQuick Ratio = (CA - Inventory) / CL (>1.0 healthy)\nCash Ratio = Cash / CL\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(942,'finance/accounting/ratio_analysis.md',3,'','social_sciences',replace('## Leverage\n```\nDebt/Equity = Total Debt / Equity\nDebt/EBITDA = Total Debt / EBITDA (<3x investment grade)\nInterest Coverage = EBIT / Interest Expense (>3x safe)\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(943,'finance/accounting/ratio_analysis.md',4,'','social_sciences',replace('## Efficiency\n```\nAsset Turnover = Revenue / Total Assets\nInventory Days = (Inventory / COGS) × 365\nReceivable Days = (AR / Revenue) × 365\nPayable Days = (AP / COGS) × 365\nCash Conversion Cycle = Inv Days + Rec Days - Pay Days\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(944,'finance/accounting/ratio_analysis.md',5,'','social_sciences',replace('## Valuation\n```\nP/E = Price / EPS (S&P 500 avg: 15-20x)\nEV/EBITDA = Enterprise Value / EBITDA (varies by industry)\nP/B = Price / Book Value per Share\nPEG = (P/E) / EPS Growth Rate (< 1 = undervalued)\n```\nEV = Market Cap + Debt - Cash','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(945,'finance/accounting/valuation_methods.md',0,'','social_sciences','# Valuation Methods','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(946,'finance/accounting/valuation_methods.md',1,'','social_sciences',replace('## DCF (Discounted Cash Flow)\n```\nValue = Σ FCF_t / (1+r)^t + Terminal Value / (1+r)^n\nTerminal Value = FCF_{n+1} / (r - g)  [Gordon Growth]\n```\n- r: WACC for FCFF, cost of equity for FCFE\n- g: perpetual growth rate (typically 2-3%, ≤ GDP growth)\n- Most sensitive to: discount rate and terminal growth','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(947,'finance/accounting/valuation_methods.md',2,'','social_sciences',replace('## WACC\n```\nWACC = (E/V)×R_e + (D/V)×R_d×(1-t)\n```\n- E: market cap, D: market value of debt, V = E+D\n- R_e: cost of equity (from CAPM)\n- R_d: cost of debt (yield on bonds)\n- t: corporate tax rate','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(948,'finance/accounting/valuation_methods.md',3,'','social_sciences',replace('## Comparable Company Analysis (Comps)\n1. Select peer group (same industry, size, growth)\n2. Calculate multiples: EV/EBITDA, P/E, EV/Revenue\n3. Apply median multiple to target''s metric\n4. Adjust for growth differential, margins, risk','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(949,'finance/accounting/valuation_methods.md',4,'','social_sciences',replace('## Precedent Transactions\nSame as comps but using M&A transaction multiples.\nInclude control premium (typically 20-40%).','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(950,'finance/accounting/valuation_methods.md',5,'','social_sciences',replace('## LBO Valuation\n```\nEntry: EV = EBITDA × Entry Multiple\nDebt: typically 4-6x EBITDA\nEquity: EV - Debt\nExit: EV_exit = EBITDA_exit × Exit Multiple\nIRR: (Equity_exit / Equity_entry)^(1/years) - 1\n```\nTarget IRR: 20-25% for PE firms.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(951,'finance/accounting/valuation_methods.md',6,'','social_sciences',replace('## When to use\n- DCF: intrinsic value, stable cash flows, long-term view\n- Comps: relative value, liquid markets, quick estimate\n- Precedent: M&A pricing, control premium\n- LBO: PE, leveraged transactions','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(952,'finance/derivatives/futures_and_forwards.md',0,'','social_sciences','# Futures and Forwards','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(953,'finance/derivatives/futures_and_forwards.md',1,'','social_sciences',replace('## Forward Price (no income)\n```\nF = S × e^(rT)\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(954,'finance/derivatives/futures_and_forwards.md',2,'','social_sciences',replace('## Forward Price (continuous dividend yield q)\n```\nF = S × e^((r-q)T)\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(955,'finance/derivatives/futures_and_forwards.md',3,'','social_sciences',replace('## Forward Price (storage cost u, convenience yield y)\n```\nF = S × e^((r+u-y)T)\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(956,'finance/derivatives/futures_and_forwards.md',4,'','social_sciences',replace('## Cost of Carry\n```\nF = S × e^(cT)  where c = r + u - q - y\n```\n- r: risk-free rate, u: storage cost\n- q: dividend yield, y: convenience yield','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(957,'finance/derivatives/futures_and_forwards.md',5,'','social_sciences',replace('## Basis and Convergence\n```\nBasis = Spot - Futures\n```\nAt expiry: basis → 0 (convergence). Before expiry: basis can be positive (backwardation) or negative (contango).','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(958,'finance/derivatives/futures_and_forwards.md',6,'','social_sciences',replace('## Futures vs Forwards\n- Futures: exchange-traded, standardized, daily settlement (margin)\n- Forwards: OTC, customizable, settlement at expiry\n- Credit risk: futures have clearinghouse guarantee; forwards have counterparty risk','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(959,'finance/derivatives/futures_and_forwards.md',7,'','social_sciences',replace('## Hedging with Futures\n```\nOptimal contracts = h* × (Q_exposure / Q_contract)\nh* = ρ(ΔS,ΔF) × σ(ΔS) / σ(ΔF)\n```','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(960,'finance/derivatives/futures_and_forwards.md',8,'','social_sciences',replace('## Mark-to-Market (Daily Settlement)\nDaily P&L = (F_today - F_yesterday) × contract_size × num_contracts\nMargin call if balance < maintenance margin.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(961,'finance/derivatives/greeks_and_sensitivities.md',0,'','social_sciences','# Greeks — Option Sensitivities','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(962,'finance/derivatives/greeks_and_sensitivities.md',1,'','social_sciences',replace('## Delta (Δ)\n```\nΔ = ∂V/∂S = N(d1) for calls, N(d1)-1 for puts\n```\n- Range: 0 to 1 (calls), -1 to 0 (puts)\n- ATM ≈ 0.50, deep ITM ≈ 1.0, deep OTM ≈ 0','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(963,'finance/derivatives/greeks_and_sensitivities.md',2,'','social_sciences',replace('## Gamma (Γ)\n```\nΓ = ∂²V/∂S² = N''(d1) / (S×σ×√T)\n```\n- Rate of change of delta. Highest ATM near expiry.\n- Long gamma = profits from large moves (straddle).\n- Short gamma = risk from large moves (selling options).','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(964,'finance/derivatives/greeks_and_sensitivities.md',3,'','social_sciences',replace('## Theta (Θ)\n```\nΘ = ∂V/∂t ≈ -(S×N''(d1)×σ)/(2√T) - r×K×e^(-rT)×N(d2)\n```\nTime decay. Usually negative (options lose value daily).\nATM options decay fastest near expiry.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(965,'finance/derivatives/greeks_and_sensitivities.md',4,'','social_sciences',replace('## Vega (ν)\n```\nν = ∂V/∂σ = S×√T×N''(d1)\n```\nSensitivity to implied vol. Highest ATM, longer-dated options.\nLong vega = profits from vol increase. Short vega = profits from vol decrease.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(966,'finance/derivatives/greeks_and_sensitivities.md',5,'','social_sciences',replace('## Rho (ρ)\n```\nρ = ∂V/∂r = K×T×e^(-rT)×N(d2) for calls\n```\nSensitivity to interest rates. Small effect except for long-dated options.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(967,'finance/derivatives/greeks_and_sensitivities.md',6,'','social_sciences',replace('## Portfolio Greeks\n```\nPortfolio Delta = Σ Δ_i × position_i\nPortfolio Gamma = Σ Γ_i × position_i\n```\nDelta-neutral: portfolio Δ = 0 (hedged against small moves).\nGamma-neutral: portfolio Γ = 0 (hedged against large moves).','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(968,'finance/derivatives/options_pricing.md',0,'','social_sciences','# Options Pricing','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(969,'finance/derivatives/options_pricing.md',1,'','social_sciences',replace('## Black-Scholes-Merton (European options)\n```\nC = S×N(d1) - K×e^(-rT)×N(d2)\nP = K×e^(-rT)×N(-d2) - S×N(-d1)\n\nd1 = [ln(S/K) + (r + σ²/2)T] / (σ√T)\nd2 = d1 - σ√T\n```\n- S: spot price, K: strike, r: risk-free rate\n- T: time to expiry (years), σ: implied volatility\n- N(): cumulative normal distribution','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(970,'finance/derivatives/options_pricing.md',2,'','social_sciences',replace('## Put-Call Parity\n```\nC - P = S - K×e^(-rT)\n```\nArbitrage relationship. If violated, riskless profit exists.','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(971,'finance/derivatives/options_pricing.md',3,'','social_sciences',replace('## Binomial Model (American options)\n1. Build price tree: u = e^(σ√Δt), d = 1/u\n2. Risk-neutral probability: p = (e^(rΔt) - d)/(u - d)\n3. Calculate payoff at terminal nodes\n4. Backward induction: check early exercise at each node\n5. American option ≥ European option (early exercise premium)','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(972,'finance/derivatives/options_pricing.md',4,'','social_sciences',replace('## Monte Carlo for Options\n- Simulate N paths of underlying price\n- Calculate payoff per path\n- Average discounted payoffs = option price\n- Standard error decreases as 1/√N','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(973,'finance/derivatives/options_pricing.md',5,'','social_sciences',replace('## Assumptions / Limitations\n- BSM assumes: constant vol, no dividends, European exercise, no jumps\n- Real markets: vol smile/skew, stochastic vol, jump-diffusion','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(974,'finance/papers/paper_a_new_g_family_properties_characterizations_different_estima.md',0,'','social_sciences','# A New G Family: Properties, Characterizations, Different Estimation Methods and PORT-VaR Analysis for U.K. Insurance Claims and U.S. House Prices Data Sets','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(975,'finance/papers/paper_a_new_g_family_properties_characterizations_different_estima.md',1,'','social_sciences',replace('## Source\n- Published: 2025\n- API: semantic_scholar\n- URL: https://www.semanticscholar.org/paper/1b0ab1a13c44977e367361305da432fe5adc2cb6\n- Retrieved: 2026-03-21','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(976,'finance/papers/paper_a_new_g_family_properties_characterizations_different_estima.md',2,'','social_sciences',replace('## Core Insight\nThis paper introduces a new class of probability distributions, termed the generated log exponentiated polynomial (GLEP) family, designed to enhance flexibility in modeling complex real financial data. The proposed family is constructed through a novel cumulative distribution function that combines logarithmic and exponentiated polynomial structures, allowing for rich distributional shapes and tail behaviors. We present comprehensive mathematical properties, including useful series expansions fo','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(977,'finance/papers/paper_a_new_g_family_properties_characterizations_different_estima.md',3,'','social_sciences',replace('## Key Concepts\n- **Maximum Likelihood Estimation**\n- **Right Tail Anderson**\n- **Left Tail Anderson**\n- **Tail Value**\n- **Tail Variance**\n- **Tail Mean Variance**\n- **Peaks Over Random Threshold Value**','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(978,'finance/papers/paper_a_new_g_family_properties_characterizations_different_estima.md',4,'','social_sciences',replace('## Practical Application\nThis research is relevant to social sciences / finance.\nKey takeaway: This paper introduces a new class of probability distributions, termed the generated log exponentiated polynomial (GLEP) family, designed to enhance flexibility in modeling complex real financial data','\n',char(10)),'2026-03-25 17:19:27');
