INSERT INTO vector_chunks_backup_20260327 VALUES(981,'finance/papers/paper_end_to_end_training_for_unified_tokenization_and_latent_deno.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-23\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.22283v1\n- Retrieved: 2026-03-24','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(982,'finance/papers/paper_end_to_end_training_for_unified_tokenization_and_latent_deno.md',2,'','social_sciences',replace('## Core Insight\nLatent diffusion models (LDMs) enable high-fidelity synthesis by operating in learned latent spaces. However, training state-of-the-art LDMs requires complex staging: a tokenizer must be trained first, before the diffusion model can be trained in the frozen latent space. We propose UNITE - an autoencoder architecture for unified tokenization and latent diffusion. UNITE consists of a Generative Encoder that serves as both image tokenizer and latent generator via weight sharing. Our key insight is','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(983,'finance/papers/paper_end_to_end_training_for_unified_tokenization_and_latent_deno.md',3,'','social_sciences',replace('## Key Concepts\n- **Generative Encoder**','\n',char(10)),'2026-03-25 17:19:27');
