INSERT INTO vector_chunks_backup_20260327 VALUES(992,'finance/papers/paper_generation_models_know_space_unleashing_implicit_3d_priors_f.md',0,'','social_sciences','# Generation Models Know Space: Unleashing Implicit 3D Priors for Scene Understanding','2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(993,'finance/papers/paper_generation_models_know_space_unleashing_implicit_3d_priors_f.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-19\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.19235v1\n- Retrieved: 2026-03-21','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(994,'finance/papers/paper_generation_models_know_space_unleashing_implicit_3d_priors_f.md',2,'','social_sciences',replace('## Core Insight\nWhile Multimodal Large Language Models demonstrate impressive semantic capabilities, they often suffer from spatial blindness, struggling with fine-grained geometric reasoning and physical dynamics. Existing solutions typically rely on explicit 3D modalities or complex geometric scaffolding, which are limited by data scarcity and generalization challenges. In this work, we propose a paradigm shift by leveraging the implicit spatial prior within large-scale video generation models. We posit that','\n',char(10)),'2026-03-25 17:19:27');
INSERT INTO vector_chunks_backup_20260327 VALUES(995,'finance/papers/paper_generation_models_know_space_unleashing_implicit_3d_priors_f.md',3,'','social_sciences',replace('## Key Concepts\n- **While Multimodal Large Language Models**\n- **Video Extracted Generative Awareness**\n- **Latent World Simulator**','\n',char(10)),'2026-03-25 17:19:27');
