INSERT INTO vector_chunks_backup_20260327 VALUES(1022,'finance/papers/paper_worldcache_content_aware_caching_for_accelerated_video_world.md',0,'','social_sciences','# WorldCache: Content-Aware Caching for Accelerated Video World Models','2026-03-25 17:19:28');
INSERT INTO vector_chunks_backup_20260327 VALUES(1023,'finance/papers/paper_worldcache_content_aware_caching_for_accelerated_video_world.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-23\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.22286v1\n- Retrieved: 2026-03-24','\n',char(10)),'2026-03-25 17:19:28');
INSERT INTO vector_chunks_backup_20260327 VALUES(1024,'finance/papers/paper_worldcache_content_aware_caching_for_accelerated_video_world.md',2,'','social_sciences',replace('## Core Insight\nDiffusion Transformers (DiTs) power high-fidelity video world models but remain computationally expensive due to sequential denoising and costly spatio-temporal attention. Training-free feature caching accelerates inference by reusing intermediate activations across denoising steps; however, existing methods largely rely on a Zero-Order Hold assumption i.e., reusing cached features as static snapshots when global drift is small. This often leads to ghosting artifacts, blur, and motion inconsiste','\n',char(10)),'2026-03-25 17:19:28');
INSERT INTO vector_chunks_backup_20260327 VALUES(1025,'finance/papers/paper_worldcache_content_aware_caching_for_accelerated_video_world.md',3,'','social_sciences',replace('## Key Concepts\n- **Diffusion Transformers**\n- **Order Hold**\n- **Constrained Dynamical Caching**\n- **On Cosmos**','\n',char(10)),'2026-03-25 17:19:28');
