INSERT INTO vector_chunks_backup_20260327 VALUES(1204,'marketing/papers/paper_computational_modeling_of_rna_protein_binding_interactions_u.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-23\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.22269v1\n- Retrieved: 2026-03-24','\n',char(10)),'2026-03-25 17:19:29');
INSERT INTO vector_chunks_backup_20260327 VALUES(1205,'marketing/papers/paper_computational_modeling_of_rna_protein_binding_interactions_u.md',2,'','social_sciences',replace('## Core Insight\nRNA binding proteins play a crucial role in post-transcriptional gene regulation by controlling the transport, processing, and translation of their target RNAs. Post-transcriptional gene regulation leads to the differential expression of genetic material and loss of regulation or over-regulation relates to a large range of cancers and diseases - many of which have directly been associated with RNA binding proteins and their target RNAs. To understand RNA, RNA binding proteins, and how they funct','\n',char(10)),'2026-03-25 17:19:29');
