INSERT INTO vector_chunks_backup_20260327 VALUES(1209,'marketing/papers/paper_covr_r_reason_aware_composed_video_retrieval.md',0,'','social_sciences','# CoVR-R:Reason-Aware Composed Video Retrieval','2026-03-25 17:19:29');
INSERT INTO vector_chunks_backup_20260327 VALUES(1210,'marketing/papers/paper_covr_r_reason_aware_composed_video_retrieval.md',1,'','social_sciences',replace('## Source\n- Published: 2026-03-20\n- API: arxiv\n- URL: http://arxiv.org/abs/2603.20190v1\n- Retrieved: 2026-03-23','\n',char(10)),'2026-03-25 17:19:29');
INSERT INTO vector_chunks_backup_20260327 VALUES(1211,'marketing/papers/paper_covr_r_reason_aware_composed_video_retrieval.md',2,'','social_sciences',replace('## Core Insight\nComposed Video Retrieval (CoVR) aims to find a target video given a reference video and a textual modification. Prior work assumes the modification text fully specifies the visual changes, overlooking after-effects and implicit consequences (e.g., motion, state transitions, viewpoint or duration cues) that emerge from the edit. We argue that successful CoVR requires reasoning about these after-effects. We introduce a reasoning-first, zero-shot approach that leverages large multimodal models to (','\n',char(10)),'2026-03-25 17:19:29');
