INSERT INTO vector_chunks_backup_20260327 VALUES(1229,'marketing/papers/paper_fintradebench_a_financial_reasoning_benchmark_for_llms.md',2,'','social_sciences',replace('## Core Insight\nReal-world financial decision-making is a challenging problem that requires reasoning over heterogeneous signals, including company fundamentals derived from regulatory filings and trading signals computed from price dynamics. Recently, with the advancement of Large Language Models (LLMs), financial analysts have begun to use them for financial decision-making tasks. However, existing financial question answering benchmarks for testing these models primarily focus on company balance sheet data a','\n',char(10)),'2026-03-25 17:19:29');
