INSERT INTO vector_chunks_backup_20260327 VALUES(1235,'marketing/papers/paper_from_masks_to_pixels_and_meaning_a_new_taxonomy_benchmark_an.md',2,'','social_sciences',replace('## Core Insight\nExisting tampering detection benchmarks largely rely on object masks, which severely misalign with the true edit signal: many pixels inside a mask are untouched or only trivially modified, while subtle yet consequential edits outside the mask are treated as natural. We reformulate VLM image tampering from coarse region labels to a pixel-grounded, meaning and language-aware task. First, we introduce a taxonomy spanning edit primitives (replace/remove/splice/inpaint/attribute/colorization, etc.) a','\n',char(10)),'2026-03-25 17:19:29');
