INSERT INTO vector_chunks_backup_20260327 VALUES(1241,'marketing/papers/paper_greater_accessibility_can_amplify_discrimination_in_generati.md',2,'','social_sciences',replace('## Core Insight\nHundreds of millions of people rely on large language models (LLMs) for education, work, and even healthcare. Yet these models are known to reproduce and amplify social biases present in their training data. Moreover, text-based interfaces remain a barrier for many, for example, users with limited literacy, motor impairments, or mobile-only devices. Voice interaction promises to expand accessibility, but unlike text, speech carries identity cues that users cannot easily mask, raising concerns ab','\n',char(10)),'2026-03-25 17:19:29');
