INSERT INTO vector_chunks_backup_20260327 VALUES(1253,'marketing/papers/paper_musteernet_human_reaction_generation_from_videos_via_observa.md',2,'','social_sciences',replace('## Core Insight\nVideo-driven human reaction generation aims to synthesize 3D human motions that directly react to observed video sequences, which is crucial for building human-like interactive AI systems. However, existing methods often fail to effectively leverage video inputs to steer human reaction synthesis, resulting in reaction motions that are mismatched with the content of video sequences. We reveal that this limitation arises from a severe relational distortion between visual observations and reaction','\n',char(10)),'2026-03-25 17:19:29');
