INSERT INTO vector_chunks_backup_20260327 VALUES(1259,'marketing/papers/paper_nemotron_cascade_2_post_training_llms_with_cascade_rl_and_mu.md',2,'','social_sciences',replace('## Core Insight\nWe introduce Nemotron-Cascade 2, an open 30B MoE model with 3B activated parameters that delivers best-in-class reasoning and strong agentic capabilities. Despite its compact size, its mathematical and coding reasoning performance approaches that of frontier open models. It is the second open-weight LLM, after DeepSeekV3.2-Speciale-671B-A37B, to achieve Gold Medal-level performance in the 2025 International Mathematical Olympiad (IMO), the International Olympiad in Informatics (IOI), and the ICP','\n',char(10)),'2026-03-25 17:19:29');
